/** A variant's `files` record for one file. */
export function logoFiles(format, src) {
    return format === "svg" ? { svg: src } : format === "png" ? { png: src } : { jpg: src };
}
/** In preference order: a record that carries more than one keeps the first. */
const LOGO_FORMATS = ["svg", "png", "jpg"];
/** A variant's one file and its format, or `undefined` when it has none. Readers use this, never `files.svg`. */
export function logoVariantFile(variant) {
    for (const format of LOGO_FORMATS) {
        const src = variant?.files?.[format]?.trim();
        if (src)
            return { src, format };
    }
    return undefined;
}
/** The variant a consumer should use for `kind` on `background`: an exact match, else one that works on any ground. */
export function pickLogoVariant(system, kind, background, select = {}) {
    const all = (system?.variants ?? []).filter((variant) => variant.kind === kind && (variant.background === background || variant.background === "any"));
    // A matching ground beats `any`, as before; selectors narrow within that order.
    const ordered = [...all.filter((variant) => variant.background === background), ...all.filter((variant) => variant.background === "any")];
    const wanted = select.name?.trim().toLowerCase();
    const named = wanted ? ordered.filter((variant) => variant.id.toLowerCase() === wanted || variant.name?.trim().toLowerCase() === wanted) : [];
    // A requested name that matches nothing falls back to the default variants, never to another name.
    const pool = named.length ? named : ordered;
    return pickByLocale(pool, select.locale);
}
/** Exact locale, then its language (`de-CH` → `de`), then a variant for any language, then the first. */
function pickByLocale(variants, locale) {
    const unlocalized = variants.filter((variant) => !variant.locale);
    if (!locale)
        return unlocalized[0] ?? variants[0];
    const wanted = locale.toLowerCase();
    const language = wanted.split("-")[0];
    return (variants.find((variant) => variant.locale?.toLowerCase() === wanted) ??
        variants.find((variant) => variant.locale?.toLowerCase().split("-")[0] === language) ??
        unlocalized[0] ??
        variants[0]);
}
