/**
 * Font and logo resolution for a **published** brand kit document (`brandkit.json`).
 *
 * The rest of `core` speaks the authoring `BrandKit`. This module speaks the published artifact,
 * because that is what consuming products actually load over the network — and every one of them
 * needs the same three answers: which font families exist, what `@font-face` CSS to inject, and
 * which logo file to show for a given kind and mode.
 *
 * It lived in Template Studio, where it was the only implementation in the ecosystem. Any second
 * adopter would have written its own, with its own idea of how to fall back from `files` to `faces`
 * or from `src` to `url` to `publicUrl`. Those shapes are the package's business, so they live here.
 */
import { logoVariantFile, pickLogoVariant } from "./logos.js";
import { normalizeLogoSystem } from "./normalize-fields.js";
import { fontFaceMetricDeclarations, normalizeFontFaceMetrics } from "./font-metrics.js";
function isObject(value) {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}
function firstString(...values) {
    for (const value of values) {
        if (typeof value === "string" && value)
            return value;
    }
    return undefined;
}
function isAbsoluteUrl(value) {
    return /^[a-z][a-z0-9+.-]*:/i.test(value) || value.startsWith("//");
}
/** Published documents may store asset paths relative to the kit's own `baseUrl`. */
export function resolvePublishedUrl(value, baseUrl) {
    if (typeof value !== "string" || !value)
        return undefined;
    if (isAbsoluteUrl(value))
        return value;
    if (!baseUrl)
        return value;
    return new URL(value.replace(/^\/+/, ""), `${baseUrl}/`).toString();
}
function resolveFontFiles(font, baseUrl) {
    if (!Array.isArray(font.faces))
        return [];
    return font.faces
        .filter(isObject)
        .flatMap((face) => {
        const faceWeight = typeof face.weight === "string" || typeof face.weight === "number" ? face.weight : undefined;
        const faceStyle = typeof face.style === "string" ? face.style : "normal";
        return Array.isArray(face.files)
            ? face.files.filter(isObject).map((file) => ({
                src: resolvePublishedUrl(file.src, baseUrl),
                weight: typeof file.weight === "string" || typeof file.weight === "number" ? file.weight : faceWeight,
                style: typeof file.style === "string" ? file.style : faceStyle,
                format: typeof file.format === "string" ? file.format : undefined,
                ...normalizeFontFaceMetrics(face),
            }))
            : [];
    })
        .filter((file) => file.src);
}
/** Declared face weights, from `faces[]` (published families carry no `weights` field). */
function resolveFaceWeights(font) {
    const weights = new Set();
    for (const face of Array.isArray(font.faces) ? font.faces.filter(isObject) : []) {
        const parsed = Number(face.weight);
        if (Number.isFinite(parsed))
            weights.add(parsed);
    }
    return [...weights].sort((a, b) => a - b);
}
function resolveFont(font, baseUrl) {
    return {
        id: firstString(font.id),
        family: firstString(font.family),
        source: firstString(font.source),
        category: firstString(font.category),
        cssUrl: resolvePublishedUrl(font.cssUrl, baseUrl),
        files: resolveFontFiles(font, baseUrl),
        faceWeights: resolveFaceWeights(font),
    };
}
/**
 * Font families keyed by id. The public contract uses a map so assignments have one lookup path.
 */
export function resolveBrandFonts(kit, baseUrl) {
    const fonts = kit.fonts;
    if (!isObject(fonts))
        return {};
    return Object.fromEntries(Object.entries(fonts)
        .filter(([, font]) => isObject(font))
        .map(([id, font]) => [id, resolveFont({ id, ...font }, baseUrl)]));
}
/** `@font-face` rules for every downloadable file. Families with only a `cssUrl` emit nothing —
 *  they are served by the stylesheet from `createFontStylesheetUrls`. */
export function createFontFaceCss(fonts) {
    return Object.values(fonts)
        .flatMap((font) => font.files.map((file) => {
        const format = file.format ? ` format("${file.format}")` : "";
        return (`@font-face{font-family:"${font.family}";src:url("${file.src}")${format};` +
            `font-weight:${file.weight ?? 400};font-style:${file.style ?? "normal"};` +
            fontFaceMetricDeclarations(file).map(([name, value]) => `${name}:${value};`).join("") +
            "font-display:swap;}");
    }))
        .join("\n");
}
export function createFontStylesheetUrls(fonts) {
    return [...new Set(Object.values(fonts).map((font) => font.cssUrl).filter((url) => Boolean(url)))];
}
/**
 * The logo for one kind and mode, with its governance metadata.
 *
 * Canonical logo selection is driven only by `logoSystem` and each variant's one file (SVG or PNG).
 */
export function resolveBrandLogo(kit, kind, mode, baseUrl, select) {
    const variant = pickLogoVariant(normalizeLogoSystem(kit.logoSystem), kind === "icon" ? "mark" : "primary", mode, select);
    const file = logoVariantFile(variant);
    const src = resolvePublishedUrl(file?.src, baseUrl);
    if (!src || !file)
        return null;
    return {
        kind,
        mode,
        src,
        format: file.format,
        assetId: variant?.id,
        name: variant?.name,
    };
}
