import { createContext, useCallback, useContext, useState, useSyncExternalStore } from 'react';

/**
 * The corner PageEditor's floating toolbar (page count, Add, Reorder, document options, zoom)
 * sits in. A template sets where it starts (`toolbarPosition`); a user moves it from the zoom menu,
 * and that choice is kept in the browser for the template's origin.
 */
export type ToolbarPosition = 'bottom-right' | 'bottom-left' | 'top-right' | 'top-left';

export const DEFAULT_TOOLBAR_POSITION: ToolbarPosition = 'bottom-right';

/** Reading order of the corners, as the zoom menu's 2 × 2 picker lays them out. */
export const TOOLBAR_POSITIONS: readonly ToolbarPosition[] = ['top-left', 'top-right', 'bottom-left', 'bottom-right'];

/** A floating bar's corner, 16px in. Literal classes, so Tailwind generates them. */
export const TOOLBAR_CORNER_CLASS: Record<ToolbarPosition, string> = {
  'bottom-right': 'uhuu:right-4 uhuu:bottom-4',
  'bottom-left': 'uhuu:left-4 uhuu:bottom-4',
  'top-right': 'uhuu:right-4 uhuu:top-4',
  'top-left': 'uhuu:left-4 uhuu:top-4',
};

const STORAGE_KEY = 'uhuu-editor-toolbar-position';

export function isToolbarPosition(value: unknown): value is ToolbarPosition {
  return typeof value === 'string' && (TOOLBAR_POSITIONS as readonly string[]).includes(value);
}

/** The user's corner, if they picked one. Storage can be missing or throw (a sandboxed iframe). */
export function readStoredToolbarPosition(): ToolbarPosition | null {
  try {
    const stored = typeof window === 'undefined' ? null : window.localStorage?.getItem(STORAGE_KEY);
    return isToolbarPosition(stored) ? stored : null;
  } catch {
    return null;
  }
}

// Every toolbar on the page follows a corner a user picks.
const storedPositionListeners = new Set<() => void>();
const subscribeToStoredPosition = (onChange: () => void) => {
  storedPositionListeners.add(onChange);
  return () => { storedPositionListeners.delete(onChange); };
};
// The server has no stored corner: hydration renders the template's, then the user's.
const noStoredPosition = () => null;

function storeToolbarPosition(position: ToolbarPosition) {
  try {
    window.localStorage?.setItem(STORAGE_KEY, position);
  } catch {
    // Not remembered: the toolbar still moves for this session.
  }
  storedPositionListeners.forEach((onChange) => onChange());
}

/** The user's corner, else the template's, else bottom right; and a setter that remembers it. */
export function useToolbarPosition(initial?: ToolbarPosition): [ToolbarPosition, (position: ToolbarPosition) => void] {
  const stored = useSyncExternalStore(subscribeToStoredPosition, readStoredToolbarPosition, noStoredPosition);
  // Where storage is unavailable, the pick still holds for this session.
  const [picked, setPicked] = useState<ToolbarPosition | null>(null);
  const position = picked ?? stored ?? (isToolbarPosition(initial) ? initial : DEFAULT_TOOLBAR_POSITION);
  const setPosition = useCallback((next: ToolbarPosition) => {
    if (!isToolbarPosition(next)) return;
    setPicked(next);
    storeToolbarPosition(next);
  }, []);
  return [position, setPosition];
}

export interface ToolbarMenuPlacement {
  /** Menus open away from the edge the toolbar sits on. */
  side: 'top' | 'bottom';
  /** And line up with the toolbar's outer corner. */
  align: 'start' | 'end';
}

export function toolbarMenuPlacement(position: ToolbarPosition): ToolbarMenuPlacement {
  return {
    side: position.startsWith('top') ? 'bottom' : 'top',
    align: position.endsWith('left') ? 'start' : 'end',
  };
}

const ToolbarPlacementContext = createContext<ToolbarMenuPlacement>(toolbarMenuPlacement(DEFAULT_TOOLBAR_POSITION));

export const ToolbarPlacementProvider = ToolbarPlacementContext.Provider;

/** Where a menu opened from the toolbar goes; menus outside the toolbar get the bottom-right default. */
export function useToolbarMenuPlacement(): ToolbarMenuPlacement {
  return useContext(ToolbarPlacementContext);
}
