/**
 * Where a template's kit comes from, and the assets it carries: logos, governed media
 * collections and map styles. `BrandKitProvider` exposes these through
 * `useBrandKit()`; they are exported for code outside a provider.
 *
 * Relative asset paths in a published brandkit.json (`assets/logos/…`) resolve against the kit's
 * `baseUrl`, else the directory of the URL the kit was fetched from.
 *
 * Pure and DOM-free, apart from `loadBrandKit`, which takes a `fetch`.
 */
import { isPublicBrandKitJsonVersion, logoFiles, logoVariantFile, pickLogoVariant, readBrandKitMapStyle, resolveBrandKitCollectionVersion } from '@uhuu/brandkit';
import { isPlainObject, textOf } from '../utility/json.js';
import { warnOnce } from '../utility/warn-once.js';

const ABSOLUTE = /^https?:\/\//i;

/** Brand Kit's production location for published kits: `<base>/teams/<team>/kits/<kit>/brandkit.json`. */
export const BRAND_KIT_PUBLIC_BASE_URL = 'https://uhuu-brandkit.s3.eu-west-1.amazonaws.com/live';

/** The directory relative asset URLs resolve against: the kit's `baseUrl`, else `sourceUrl`'s. */
export function brandKitBaseUrl(brandKit, sourceUrl) {
  const own = isPlainObject(brandKit) ? textOf(brandKit.baseUrl) : undefined;
  if (own) return own.replace(/\/+$/, '');
  const source = textOf(sourceUrl);
  if (!source || !ABSOLUTE.test(source)) return undefined;
  try {
    return new URL('.', source).toString().replace(/\/+$/, '');
  } catch {
    return undefined;
  }
}

/** Absolute against `base` when relative; `undefined` for anything that is not a plain URL. */
export function resolveBrandKitUrl(value, base) {
  const url = textOf(value);
  if (!url || /\s/.test(url)) return undefined;
  if (ABSOLUTE.test(url) || /^data:/i.test(url)) return url;
  if (/^[a-z][a-z0-9+.-]*:/i.test(url) || url.startsWith('//')) return undefined;
  if (!base) return url;
  try {
    return new URL(url, `${base}/`).toString();
  } catch {
    return undefined;
  }
}

const PINNED = /\/versions\/v\d+\//;
// A published version's name as Brand Kit writes it: `v1`, `v2`… (`v0` is a kit with none yet).
const VERSION = /^v[1-9]\d*$/;
// A kit's root document, `…/kits/<kit>/brandkit.json`, which follows every publish.
const ROOT_DOCUMENT = /^([^?#]*\/kits\/[^/?#]+)\/brandkit\.json([?#].*)?$/i;

/** True for an immutable `…/versions/vN/…` URL (in its path), the only brand URL a publish cannot change. */
export function isPinnedBrandKitUrl(url) {
  return typeof url === 'string' && PINNED.test(url.replace(/[?#].*$/, ''));
}

/** `…/kits/<kit>/brandkit.json` and `vN` → `…/kits/<kit>/versions/vN/brandkit.json`, query and hash kept. */
function versionedBrandKitUrl(url, version) {
  const match = version && VERSION.test(version) ? ROOT_DOCUMENT.exec(url) : null;
  return match ? `${match[1]}/versions/${version}/brandkit.json${match[2] ?? ''}` : undefined;
}

/**
 * Which brand a document renders, by the platform's precedence (Brand Kit's
 * "Selection precedence"):
 *
 * 1. `payload.brand`, a reference `{ kind: 'kit', url, version }`. It is pinned when `url` is an
 *    immutable `versions/vN/brandkit.json`. A `version` (`vN`) beside the kit's root
 *    `…/kits/<kit>/brandkit.json`, which follows every publish, fetches that version's document
 *    instead. Any other URL is refused with a warning; a version alone pins nothing.
 * 2. Nothing (`none`): the template's own current `src/brand/brandkit.json` passed as `brandKit`.
 *
 * Feed the result to the provider: `<BrandKitProvider src={selection.src} brandKit={brandKit}>`.
 * With a `src`, the template's brand is what renders until (and unless) the fetched kit arrives.
 * `pinned` is true when `src` is a `versions/vN` URL, and for a preset reference (nothing is fetched).
 *
 * @param {object|null|undefined} payload
 * @returns {{ source: 'payload'|'none', src: string|null, pinned: boolean, presetId?: string }}
 */
export function brandKitSelection(payload) {
  const ref = isPlainObject(payload) && isPlainObject(payload.brand) ? payload.brand : undefined;
  if (ref?.kind === 'kit') {
    const url = resolveBrandKitUrl(ref.url) ?? null;
    const version = textOf(ref.version);
    const src = url && !isPinnedBrandKitUrl(url) ? versionedBrandKitUrl(url, version) ?? url : url;
    const pinned = isPinnedBrandKitUrl(src);
    if (src && !pinned) {
      warnOnce(
        `brand-kit-unpinned:${src}`,
        `[uhuu-components] payload.brand ${src} is not an immutable versions/vN/brandkit.json URL` +
        (version ? ` (version ${JSON.stringify(version)} pins only when it is vN beside a …/kits/<kit>/brandkit.json URL)` : '') +
        '. The template keeps its local current brand until a pinned URL is supplied.',
      );
      return { source: 'none', src: null, pinned: false };
    }
    if (src) return { source: 'payload', src, pinned };
  }
  if (ref?.kind === 'preset') {
    warnOnce(
      `brand-kit-preset:${ref.presetId}`,
      `[uhuu-components] payload.brand names preset ${String(ref.presetId)}, which the host resolves; the template renders its own brand.`,
    );
    return { source: 'payload', src: null, pinned: true, ...(textOf(ref.presetId) ? { presetId: ref.presetId } : {}) };
  }
  return { source: 'none', src: null, pinned: false };
}

/**
 * Fetches a brandkit.json. Rejects on a network error, a non-2xx response or a body that is not
 * a JSON object, so the caller can keep its fallback kit.
 *
 * @param {string} url
 * @param {{ fetch?: typeof fetch, signal?: AbortSignal }} [options]
 */
export async function loadBrandKit(url, options = {}) {
  const doFetch = options.fetch ?? globalThis.fetch;
  if (typeof doFetch !== 'function') throw new Error('[uhuu-components] loadBrandKit needs fetch');
  const response = await doFetch(url, { signal: options.signal, headers: { accept: 'application/json' } });
  if (!response.ok) throw new Error(`[uhuu-components] Brand kit ${url} answered ${response.status}`);
  let document;
  try {
    document = await response.json();
  } catch (cause) {
    // An HTML page (a login, an SPA fallback) answers 200: name the URL, not just the parser.
    throw new Error(`[uhuu-components] Brand kit ${url} is not JSON (${cause?.message ?? cause})`);
  }
  if (!isPlainObject(document)) throw new Error(`[uhuu-components] Brand kit ${url} is not a JSON object`);
  return document;
}

// --- Logos ------------------------------------------------------------------------------------

const LOGO_KIND = { primary: 'primary', logo: 'primary', lockup: 'primary', mark: 'mark', icon: 'mark', symbol: 'mark', wordmark: 'wordmark' };
// A variant's one file, SVG, PNG or JPG (in that order when a record carries more), from @uhuu/brandkit.
const fileOf = (files) => (isPlainObject(files) ? logoVariantFile({ files: { svg: textOf(files.svg), png: textOf(files.png), jpg: textOf(files.jpg) } }) : undefined);

/**
 * A logo from the kit, resolved to an absolute `src`.
 *
 * `kind` is `primary` (alias `logo`), `mark` (alias `icon`) or `wordmark`; `background` is the
 * surface it sits on, `light` (default) or `dark`. Brand Kit's `logoSystem` is read first: the
 * variant of that kind for that background, else one marked `any`, else the other background.
 * `wordmark` falls back to `primary`. Returns `null` when the kit has none.
 *
 * `name` and `locale` pick a named or language version from the logo system (Walde "Premium" in
 * German): a variant whose `id` or `name` matches, then its exact `locale`, then its language
 * (`de-CH` → `de`), then one without a locale. An unknown name gives the standard logo, never
 * another named one. Pass `payload.locale` so the document's language picks the file.
 *
 * @param {object|null|undefined} brandKit
 * @param {{ kind?: string, background?: 'light'|'dark', name?: string, locale?: string, sourceUrl?: string }} [options]
 * The logo is the variant's one file: an SVG, else a PNG, else a JPG (`format`).
 *
 * @returns {{ src: string, format: 'svg'|'png'|'jpg', alt?: string, kind: string, background?: string } | null}
 */
export function brandKitLogo(brandKit, options = {}) {
  if (!isPlainObject(brandKit)) return null;
  const kind = LOGO_KIND[String(options.kind ?? 'primary').toLowerCase()] ?? 'primary';
  const background = options.background === 'dark' ? 'dark' : 'light';
  const base = brandKitBaseUrl(brandKit, options.sourceUrl);
  const alt = textOf(brandKit.name);
  // Only a logo system names a wordmark; elsewhere it is the primary lockup.
  const found = logoFromSystem(brandKit, kind, background, base, alt, options);
  if (found || kind !== 'wordmark') return found;
  return brandKitLogo(brandKit, { ...options, kind: 'primary' });
}

/** Well-formed variants only, in the package's shape, so `pickLogoVariant` never sees malformed input. */
function logoVariants(brandKit) {
  const variants = Array.isArray(brandKit.logoSystem?.variants) ? brandKit.logoSystem.variants : [];
  return variants.flatMap((variant, index) => {
    if (!isPlainObject(variant) || !fileOf(variant.files)) return [];
    const background = ['light', 'dark', 'any'].includes(variant.background) ? variant.background : 'any';
    return [{
      ...variant,
      id: textOf(variant.id) ?? `variant-${index + 1}`,
      background,
      ...(textOf(variant.name) ? { name: textOf(variant.name) } : { name: undefined }),
      ...(textOf(variant.locale) ? { locale: textOf(variant.locale) } : { locale: undefined }),
      files: logoFiles(fileOf(variant.files).format, fileOf(variant.files).src),
    }];
  });
}

function logoFromSystem(brandKit, kind, background, base, alt, options = {}) {
  const system = { variants: logoVariants(brandKit) };
  const select = { name: textOf(options.name), locale: textOf(options.locale) };
  // `pickLogoVariant` in @uhuu/brandkit: this ground or `any`. A logo drawn only for the other
  // ground is still better than none in a document.
  const variant = pickLogoVariant(system, kind, background, select)
    ?? pickLogoVariant(system, kind, background === 'dark' ? 'light' : 'dark', select);
  if (!variant) return null;
  const file = logoVariantFile(variant);
  const src = file ? resolveBrandKitUrl(file.src, base) : undefined;
  if (!src) return null;
  return {
    src,
    format: file.format,
    alt: variant.name ?? alt,
    kind,
    background: variant.background,
    ...(variant.locale ? { locale: variant.locale } : {}),
  };
}

// --- Collections ------------------------------------------------------------------------------

/**
 * Current public collections use canonical kind/id and active-version selection. The item view
 * keeps schema order, explicit labels, custom fields and URL policy. `null` when absent.
 *
 * @param {object|null|undefined} brandKit
 * @param {string} kindOrId
 * @param {{ sourceUrl?: string, versionId?: string }} [options]
 */
export function brandKitCollection(brandKit, kindOrId, options = {}) {
  if (!isPlainObject(brandKit) || !isPlainObject(brandKit.collections)) return null;
  if (!isPublicBrandKitJsonVersion(brandKit.version)) return null;
  const selected = resolveBrandKitCollectionVersion(brandKit, kindOrId, options.versionId);
  if (!selected) return null;
  const { collectionId: id, collection, versionId, version } = selected;
  const base = brandKitBaseUrl(brandKit, options.sourceUrl);
  const schemaKeys = isPlainObject(collection.schema?.keys) ? collection.schema.keys : {};

  let entries = [];
  if (version && isPlainObject(version.items)) {
    const keys = [...Object.keys(schemaKeys).filter((key) => key in version.items), ...Object.keys(version.items).filter((key) => !(key in schemaKeys))];
    entries = keys.map((key) => [key, version.items[key]]);
  }

  const items = entries.flatMap(([key, item]) => {
    if (!isPlainObject(item)) return [];
    const src = resolveBrandKitUrl(item.src ?? item.url, base);
    if (!src) return [];
    const label = textOf(item.label) ?? textOf(schemaKeys[key]?.label) ?? textOf(item.name);
    return [{ ...item, key, src, ...(label ? { label } : {}) }];
  });

  return {
    id,
    name: textOf(collection.name),
    type: textOf(collection.type),
    versionId: versionId ?? undefined,
    items,
  };
}

// --- Map styles -------------------------------------------------------------------------------

/**
 * Canonical map styles (`extensions.maps`). Obsolete config mirrors are not read. Geometry,
 * provider selection and secrets remain template-owned. Missing styles return null.
 * @returns {import('@uhuu/brandkit').BrandKitMapStyleResult | null}
 */
export function brandKitMapStyle(brandKit, mode) {
  return readBrandKitMapStyle(brandKit, mode === 'macro' ? 'macro' : 'micro');
}
