// Scheduling for flow measurement (`Flow.Area` in its measurement pass).
//
// Frames: a hidden or background document runs no requestAnimationFrame callbacks (a second tab in a
// headless batch renderer, a preview tab the user switched away from). Flow measurement waits for a
// frame only so that observer bursts coalesce; it must never wait for a frame that does not come.
//
export const FRAME_FALLBACK_MS = 100;
/**
 * How long a page marked `hasFlow` may render without its region, or a region without its Flow,
 * before the shell warns that pagination is waiting: a loading branch may take that long on purpose.
 */
export const MISSING_FLOW_GRACE_MS = 1000;

/**
 * Run `callback` on the next animation frame, or after a timeout when no frame comes (at once in a
 * hidden document, otherwise after `fallbackMs`). Whichever fires first wins; returns a cancel
 * function.
 */
export function scheduleFlowFrame(callback, { fallbackMs = FRAME_FALLBACK_MS, win } = {}) {
  const host = win ?? (typeof window === 'undefined' ? undefined : window);
  let finished = false;
  let frameId = null;
  let timerId = null;

  const clear = () => {
    if (frameId !== null) host?.cancelAnimationFrame?.(frameId);
    if (timerId !== null) clearTimeout(timerId);
    frameId = null;
    timerId = null;
  };
  const run = () => {
    if (finished) return;
    finished = true;
    clear();
    callback();
  };

  const hidden = host?.document?.visibilityState === 'hidden';
  if (!hidden && typeof host?.requestAnimationFrame === 'function') {
    frameId = host.requestAnimationFrame(run);
    timerId = setTimeout(run, fallbackMs);
  } else {
    timerId = setTimeout(run, 0);
  }

  return () => {
    finished = true;
    clear();
  };
}
