/**
 * The one implementation of "read a laid-out Flow from the DOM".
 *
 * `Flow.Area` uses it to measure the runtime document, and hosts that run
 * their own Flow canvas (Template Studio's Design surface) use it instead of
 * re-deriving the same reads. Two copies of this rounding is the one way a
 * shared chunk plan can still disagree between an editor and its delivery: the
 * planner is deterministic, so a half-pixel difference here is the only thing
 * that can move a page boundary.
 */

export type StaticFlowItemMeta = {
  breakBefore?: boolean;
  breakAfter?: boolean;
  keepWithNext?: boolean | number;
  avoidBreakInside?: boolean;
  groupKey?: string;
  /** A split item (`Flow.Text`): fewest lines on a piece that ends a page. Default 2. */
  orphans?: number;
  /** A split item: fewest lines on the piece that starts the next page. Default 2. */
  widows?: number;
  /**
   * The screen view (`PageEditor` `view="screen"`): where print would scale the item onto a page of
   * its own, it is drawn whole and its sheet grows to hold it. Print ignores it.
   */
  growSheet?: boolean;
};

/**
 * The lines of an item's `Flow.Text`, in layout px from the item's measured origin (its
 * bottom, margin included, less its measured height): each line box's top and bottom, and the text
 * offset (UTF-16, across the FlowText's text nodes in order) where it starts. `end` is the text's
 * length; `justify`: the text is justified, so a piece that ends mid-paragraph justifies its last
 * line too.
 */
export type StaticFlowItemLines = {
  /** `hyphen`: the line ends with a hyphen the browser drew (`hyphens: auto`, a soft hyphen). */
  lines: Array<{ top: number; bottom: number; start: number; hyphen?: boolean }>;
  end: number;
  justify: boolean;
  /** The text's computed CSS `orphans` / `widows`, where the browser reports them; an item's meta wins. */
  orphans?: number;
  widows?: number;
};

/**
 * Why an item's FlowText cannot split, or splits but may not match its plan:
 * - `multiple-flow-text`: the item holds more than one FlowText (it is planned whole);
 * - `inline-flow-text`: the FlowText element is not a block (`as="span"`), so its lines are not
 *   its own (planned whole);
 * - `unsupported-content`: FlowText children other than text and inline text elements (planned
 *   whole; FlowText marks itself `data-uhuu-flow-text-unsplittable`);
 * - `rewrapping-text-wrap`: `text-wrap: balance | pretty` re-flows a slice, so a piece may wrap
 *   differently from the plan (split anyway).
 */
export type StaticFlowTextIssue =
  | 'multiple-flow-text'
  | 'inline-flow-text'
  | 'unsupported-content'
  | 'rewrapping-text-wrap';

/** Marks the element `Flow.Text` renders. */
const FLOW_TEXT_ATTRIBUTE = 'data-uhuu-flow-text';

/**
 * The product of every ancestor CSS transform (preview fit-to-pane, host zoom), derived at read
 * time: offsetWidth is layout-space while the rect is visual-space. Chunking must run in layout
 * space — rects scale under a transform but computed margins do not, so an un-normalized
 * measurement pass silently paginates differently in a scaled preview than in the real document.
 */
export function getEffectiveScale(element: HTMLElement): number {
  const rectWidth = element.getBoundingClientRect().width;
  const layoutWidth = element.offsetWidth;
  if (!(rectWidth > 0) || !(layoutWidth > 0)) return 1;
  const scale = rectWidth / layoutWidth;
  // offsetWidth is integer-rounded; treat near-1 ratios as the untransformed common case.
  return Math.abs(scale - 1) < 0.002 ? 1 : scale;
}

/** Border-box height plus vertical margins, normalized out of `scale` into layout space. */
export function getOuterHeight(element: HTMLElement, scale = 1): number {
  const rect = element.getBoundingClientRect();
  const styles = window.getComputedStyle(element);
  const marginTop = Number.parseFloat(styles.marginTop || '0') || 0;
  const marginBottom = Number.parseFloat(styles.marginBottom || '0') || 0;
  return rect.height / scale + marginTop + marginBottom;
}

export function readItemMeta(element: HTMLElement): StaticFlowItemMeta {
  const meta: StaticFlowItemMeta = {
    breakBefore: element.dataset.uhuuFlowBreakBefore === 'true',
    breakAfter: element.dataset.uhuuFlowBreakAfter === 'true',
    keepWithNext: parseKeepWithNext(element.dataset.uhuuFlowKeepWithNext),
    avoidBreakInside: element.dataset.uhuuFlowAvoidBreakInside === 'true',
    groupKey: element.dataset.uhuuFlowGroupKey,
  };
  // Only when set: an item without them reads exactly as before.
  const orphans = parseLineCount(element.dataset.uhuuFlowOrphans);
  const widows = parseLineCount(element.dataset.uhuuFlowWidows);
  if (orphans !== undefined) meta.orphans = orphans;
  if (widows !== undefined) meta.widows = widows;
  if (element.dataset.uhuuFlowGrowSheet === 'true') meta.growSheet = true;
  return meta;
}

/** `orphans` / `widows` as attribute values: a positive whole number of lines, else unset. */
export function parseLineCount(value: string | undefined): number | undefined {
  if (!value) return undefined;
  const count = Number.parseInt(value, 10);
  return Number.isFinite(count) && count >= 1 ? count : undefined;
}

export function serializeLineCount(value: number | undefined): string | undefined {
  return typeof value === 'number' && Number.isFinite(value) && value >= 1
    ? String(Math.floor(value))
    : undefined;
}

export function parseKeepWithNext(value: string | undefined): boolean | number {
  if (!value) return false;
  if (value === 'true') return true;

  const count = Number.parseInt(value, 10);
  return Number.isFinite(count) && count > 0 ? count : false;
}

export function serializeKeepWithNext(value: StaticFlowItemMeta['keepWithNext']): string | undefined {
  if (typeof value === 'number' && Number.isFinite(value) && value > 0) {
    return String(Math.floor(value));
  }

  return value ? 'true' : undefined;
}

export function readHeaderGroupKey(element: HTMLElement): string | undefined {
  const value = element.dataset.uhuuFlowHeaderGroupKey;
  return value || undefined;
}

export function readHeaderGroupRepeats(itemElements: HTMLElement[]): Record<string, boolean> {
  const repeats: Record<string, boolean> = {};

  for (const item of itemElements) {
    const groupKey = readHeaderGroupKey(item);
    if (!groupKey) continue;
    if (item.dataset.uhuuFlowHeaderRepeat === 'false') {
      repeats[groupKey] = false;
    } else if (!(groupKey in repeats)) {
      repeats[groupKey] = true;
    }
  }

  return repeats;
}

/**
 * The header groups whose items carry `data-uhuu-flow-header-grow-sheet` (`getItemGroup`
 * `growSheet`, rendered in the screen view only): each is one unit on one sheet.
 */
export function readHeaderGroupGrows(itemElements: HTMLElement[]): Record<string, boolean> {
  const grows: Record<string, boolean> = {};

  for (const item of itemElements) {
    const groupKey = readHeaderGroupKey(item);
    if (groupKey && item.dataset.uhuuFlowHeaderGrowSheet === 'true') grows[groupKey] = true;
  }

  return grows;
}

/** `unwrapped`: heights from `readUnwrappedHeights`, used for the headers it covers. */
export function readHeaderGroupHeights(
  root: HTMLElement,
  scale = 1,
  unwrapped?: ReadonlyMap<HTMLElement, number>
): Record<string, number> {
  const heights: Record<string, number> = {};

  for (const header of Array.from(
    root.querySelectorAll<HTMLElement>('[data-uhuu-flow-group-header="true"]')
  )) {
    const groupKey = header.dataset.uhuuFlowHeaderGroupKey;
    if (!groupKey) continue;
    // A header can occur more than once in a measurement render when a group
    // is non-contiguous. Use the largest observed variant to avoid clipping.
    heights[groupKey] = Math.max(
      heights[groupKey] ?? 0,
      unwrapped?.get(header) ?? getOuterHeight(header, scale)
    );
  }

  return heights;
}

/**
 * Heights for a Flow that renders its items without wrappers (`asChild`): the items and group
 * headers that are direct children of the Flow's root.
 *
 * A wrapper is `display: flow-root`, so it holds its content's margins and its outer height is
 * exact. Without it margins collapse, between siblings and through an item's own edges (the top
 * margin of a `<p>` inside an `<li>`), so an item's own box and margins say neither how much space
 * it takes nor how much it leaves out. Positions do: an item's height is the distance from the
 * bottom of the element before it in the root (the area's top for the first) to its own bottom.
 * Each collapsed gap is counted once, before the item that follows it, and a page's first item is
 * charged the gap it followed here, at least the margin it keeps at the top of a page: a plan can
 * underfill a page by a collapsed margin, never overfill it. A group header also counts its own
 * margins, since it repeats before items it did not precede here. Items stack vertically.
 *
 * Elements inside FlowColumns columns are not in the map: columns are flex columns, whose items'
 * margins neither collapse nor leak, so their outer height is exact.
 */
export function readUnwrappedHeights(
  area: HTMLElement,
  flow: HTMLElement,
  scale = 1
): Map<HTMLElement, number> {
  const heights = new Map<HTMLElement, number>();
  let previousBottom = area.getBoundingClientRect().top;

  for (const child of Array.from(flow.children)) {
    if (!(child instanceof HTMLElement) || !child.getClientRects().length) continue;
    const bottom = child.getBoundingClientRect().bottom;
    const height = Math.max(0, bottom - previousBottom) / scale;
    previousBottom = Math.max(previousBottom, bottom);
    if (child.dataset.uhuuFlowItem === 'true') {
      heights.set(child, height);
    } else if (child.dataset.uhuuFlowGroupHeader === 'true') {
      heights.set(child, Math.max(height, getOuterHeight(child, scale)));
    }
  }

  return heights;
}

/** Every measured leaf under `root`, in `data-uhuu-flow-index` order where present. */
export function readFlowItemElements(root: HTMLElement): HTMLElement[] {
  return Array.from(root.querySelectorAll<HTMLElement>('[data-uhuu-flow-item="true"]'));
}

/**
 * The first of `items` that does not lie below the item before it in `area` (beside it, above it,
 * or in another column of a multi-column container), or `null` when they stack. A flow plans with
 * item heights that add up down the area; an item placed anywhere else makes every sum wrong.
 * Items of a Flow nested in `flow`, and items without a box, are left out.
 */
export function readUnstackedItem(area: HTMLElement, flow: HTMLElement, items: HTMLElement[]): HTMLElement | null {
  const areaRect = area.getBoundingClientRect();
  let previous: DOMRect | null = null;
  for (const item of items) {
    if (item.closest('[data-uhuu-flow="true"]') !== flow) continue;
    const rect = item.getBoundingClientRect();
    if (!(rect.width > 0) && !(rect.height > 0)) continue;
    if (rect.right <= areaRect.left + 0.5 || rect.left >= areaRect.right - 0.5) return item;
    if (previous && previous.height > 0.5 && rect.top < previous.top + 0.5) return item;
    previous = rect;
  }
  return null;
}

const PX_PER_UNIT: Record<string, number> = { px: 1, mm: 96 / 25.4, cm: 96 / 2.54, in: 96, pt: 96 / 72, pc: 16 };

/**
 * A CSS length with an absolute unit (`"20mm"`, `"0.5in"`, `"12px"`) in CSS px, or a number of
 * px; `undefined` for anything else (a relative unit, a negative value). Layout space, like every
 * other measurement here: the editor's zoom does not reach it.
 */
export function parseAbsoluteLength(value: number | string | undefined): number | undefined {
  if (typeof value === 'number') return Number.isFinite(value) && value >= 0 ? value : undefined;
  if (typeof value !== 'string') return undefined;
  const match = /^\s*(\d+(?:\.\d+)?|\.\d+)\s*(px|mm|cm|in|pt|pc)\s*$/i.exec(value);
  if (!match) return /^\s*0\s*$/.test(value) ? 0 : undefined;
  return Number.parseFloat(match[1]) * PX_PER_UNIT[match[2].toLowerCase()];
}

/**
 * The `Flow.Text` elements that belong to `item` itself: those of a Flow nested in the item
 * belong to that Flow's items.
 */
export function readItemFlowTexts(item: HTMLElement): HTMLElement[] {
  const flow = item.closest<HTMLElement>('[data-uhuu-flow="true"]');
  return Array.from(item.querySelectorAll<HTMLElement>(`[${FLOW_TEXT_ATTRIBUTE}]`))
    .filter((text) => text.closest('[data-uhuu-flow="true"]') === flow);
}

const LETTER = /[\p{L}\p{M}]/u;

function verticalEdges(style: CSSStyleDeclaration) {
  const value = (property: string) => Number.parseFloat(style.getPropertyValue(property) || '0') || 0;
  return {
    top: value('border-top-width') + value('padding-top'),
    bottom: value('border-bottom-width') + value('padding-bottom'),
  };
}

/**
 * The lines of the one `Flow.Text` in a measured item, or `undefined` when it has none or
 * cannot split (`report` says why). `height` is the item's measured height (`getOuterHeight`, or
 * `readUnwrappedHeights` for `asChild`); the lines are measured from the same origin, so a host
 * that reads both with these functions plans exactly what FlowArea plans.
 *
 * The text's own rects say where its lines are: one Range over each text node gives the node's
 * line fragments, grouped into lines across nodes by vertical position, and the offset at which
 * each line starts is found by bisection over one-character ranges, O(lines · log n) reads rather
 * than one per character. A character without a rect of its own (collapsed whitespace) belongs to
 * the next one that has one. The first line's box starts at the FlowText's content box top, the
 * last ends at its bottom, and two lines meet halfway between the glyphs of the one above and of
 * the one below: exact for uniform half-leading, and what a slice of those lines lays out at.
 */
export function readFlowTextLines(
  item: HTMLElement,
  height: number,
  scale = 1,
  report?: (issue: StaticFlowTextIssue, element: HTMLElement) => void
): StaticFlowItemLines | undefined {
  const texts = readItemFlowTexts(item);
  if (!texts.length) return undefined;
  if (texts.length > 1) {
    report?.('multiple-flow-text', item);
    return undefined;
  }
  const text = texts[0];
  if (text.hasAttribute('data-uhuu-flow-text-unsplittable')) {
    report?.('unsupported-content', text);
    return undefined;
  }
  const style = window.getComputedStyle(text);
  if (style.display === 'none') return undefined;
  if (style.display === 'inline' || style.display === 'contents') {
    report?.('inline-flow-text', text);
    return undefined;
  }
  const wrap = `${style.getPropertyValue('text-wrap-style')} ${style.getPropertyValue('text-wrap')}`;
  if (/\b(balance|pretty)\b/.test(wrap)) report?.('rewrapping-text-wrap', text);
  // The counts CSS gives the text (2 by default, where the browser reports them); the item's meta wins.
  const orphans = parseLineCount(style.getPropertyValue('orphans'));
  const widows = parseLineCount(style.getPropertyValue('widows'));

  const nodes: Text[] = [];
  const nodeStarts: number[] = [];
  let end = 0;
  const walker = document.createTreeWalker(text, NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    const textNode = node as Text;
    nodes.push(textNode);
    nodeStarts.push(end);
    end += textNode.data.length;
  }
  if (!nodes.length) return undefined;

  // Lines, from each text node's fragments in reading order: a fragment below the line so far
  // starts the next line, any other joins it (smaller type, a superscript).
  const range = document.createRange();
  const bands: Array<{ top: number; bottom: number }> = [];
  const nodeBands: Array<[number, number] | null> = [];
  for (const node of nodes) {
    range.selectNodeContents(node);
    let first = -1;
    let last = -1;
    for (const rect of Array.from(range.getClientRects())) {
      if (!(rect.height > 0)) continue;
      const band = bands[bands.length - 1];
      if (!band || (rect.top + rect.bottom) / 2 > band.bottom) {
        bands.push({ top: rect.top, bottom: rect.bottom });
      } else {
        band.top = Math.min(band.top, rect.top);
        band.bottom = Math.max(band.bottom, rect.bottom);
      }
      if (first < 0) first = bands.length - 1;
      last = bands.length - 1;
    }
    nodeBands.push(first < 0 ? null : [first, last]);
  }
  if (!bands.length) return undefined;

  const bandAt = (middle: number, first: number, last: number) => {
    let low = first;
    let high = last;
    while (low < high) {
      const center = (low + high) >> 1;
      if (bands[center].bottom >= middle) high = center;
      else low = center + 1;
    }
    return low;
  };
  // The line of the character at `offset`: its last fragment (the first character after a
  // hyphenated break also reports the hyphen on the line above), or the next character's.
  const lineOf = (node: Text, offset: number, first: number, last: number) => {
    for (let index = offset; index < node.data.length; index += 1) {
      range.setStart(node, index);
      range.setEnd(node, index + 1);
      const rects = range.getClientRects();
      for (let rectIndex = rects.length - 1; rectIndex >= 0; rectIndex -= 1) {
        const rect = rects[rectIndex];
        if (rect.height > 0) return bandAt((rect.top + rect.bottom) / 2, first, last);
      }
    }
    return last;
  };

  // Where each line starts: the first character on it, by bisection over the characters of the
  // node it starts in. The search is bracketed first from the previous line's length (lines of a
  // paragraph hold similar counts), widening until it holds the boundary: a few reads a line.
  const starts: number[] = Array.from({ length: bands.length }, () => -1);
  nodes.forEach((node, nodeIndex) => {
    const span = nodeBands[nodeIndex];
    if (!span) return;
    const [first, last] = span;
    const length = node.data.length;
    const after = (offset: number, band: number) => lineOf(node, offset, first, last) >= band;
    if (starts[first] < 0) starts[first] = nodeStarts[nodeIndex];
    let low = 0;
    let lineLength = 0;
    for (let band = first + 1; band <= last; band += 1) {
      const lineStart = low;
      let high = length;
      const estimate = lineLength || Math.ceil((length - low) / (last - band + 2));
      const guess = Math.min(length - 1, low + estimate);
      let step = Math.max(1, estimate >> 3);
      if (guess > low && after(guess, band)) {
        high = guess;
        for (let probe = guess - step; probe > low; probe = high - step) {
          if (!after(probe, band)) {
            low = probe + 1;
            break;
          }
          high = probe;
          step *= 2;
        }
      } else if (guess > low) {
        low = guess + 1;
        for (let probe = guess + step; probe < high; probe = low + step) {
          if (after(probe, band)) {
            high = probe;
            break;
          }
          low = probe + 1;
          step *= 2;
        }
      }
      while (low < high) {
        const middle = (low + high) >> 1;
        if (after(middle, band)) high = middle;
        else low = middle + 1;
      }
      // Never inside a surrogate pair.
      let offset = low;
      const code = node.data.charCodeAt(offset);
      if (offset > 0 && code >= 0xdc00 && code <= 0xdfff) offset -= 1;
      starts[band] = nodeStarts[nodeIndex] + offset;
      lineLength = Math.max(1, offset - lineStart);
    }
  });

  const nodeAt = (offset: number) => {
    let low = 0;
    let high = nodeStarts.length - 1;
    while (low < high) {
      const center = (low + high + 1) >> 1;
      if (nodeStarts[center] <= offset) low = center;
      else high = center - 1;
    }
    return low;
  };
  const characterAt = (offset: number) => {
    const nodeIndex = nodeAt(offset);
    return nodes[nodeIndex].data[offset - nodeStarts[nodeIndex]] ?? '';
  };
  // A line ends with a drawn hyphen when its last character reports a second fragment on its own
  // line: the hyphen glyph (`hyphens: auto` between letters). A soft hyphen that broke always draws
  // one; a break after anything else (a space, a hard hyphen) draws none, and an emergency break
  // between letters reports a single fragment.
  const hyphens: boolean[] = bands.map((_, band) => {
    if (band === bands.length - 1) return false;
    const offset = starts[band + 1] - 1;
    if (offset < 0) return false;
    const before = characterAt(offset);
    if (before === '\u00ad') return true;
    if (!LETTER.test(before) || !LETTER.test(characterAt(offset + 1))) return false;
    const nodeIndex = nodeAt(offset);
    const node = nodes[nodeIndex];
    const local = offset - nodeStarts[nodeIndex];
    range.setStart(node, local);
    range.setEnd(node, local + 1);
    let fragments = 0;
    for (const fragment of Array.from(range.getClientRects())) {
      const middle = (fragment.top + fragment.bottom) / 2;
      if (fragment.height > 0 && middle >= bands[band].top && middle <= bands[band].bottom) fragments += 1;
    }
    return fragments >= 2;
  });

  const rect = text.getBoundingClientRect();
  const edges = verticalEdges(style);
  const itemRect = item.getBoundingClientRect();
  const itemMarginBottom = Number.parseFloat(window.getComputedStyle(item).marginBottom || '0') || 0;
  const origin = itemRect.bottom + (itemMarginBottom - height) * scale;
  const layout = (value: number) => (value - origin) / scale;
  const contentTop = rect.top + edges.top * scale;
  const contentBottom = rect.bottom - edges.bottom * scale;

  const lines: StaticFlowItemLines['lines'] = [];
  bands.forEach((band, index) => {
    const top = index === 0 ? contentTop : (bands[index - 1].bottom + band.top) / 2;
    const bottom = index === bands.length - 1 ? contentBottom : (band.bottom + bands[index + 1].top) / 2;
    const start = index === 0 ? 0 : starts[index];
    const previous = lines[lines.length - 1];
    // A line that starts no later than the one before it holds no text of its own: one line.
    if (previous && !(start > previous.start)) {
      previous.bottom = layout(bottom);
      if (hyphens[index]) previous.hyphen = true;
      else delete previous.hyphen;
      return;
    }
    lines.push({ top: layout(top), bottom: layout(bottom), start, ...(hyphens[index] ? { hyphen: true } : {}) });
  });

  return {
    lines,
    end,
    justify: style.textAlign === 'justify',
    ...(orphans !== undefined ? { orphans } : {}),
    ...(widows !== undefined ? { widows } : {}),
  };
}

/**
 * Compact, allocation-light FNV-1a hash. Signatures are only ever compared for
 * equality, so a short hash beats keeping the full inputs as JSON — and beats
 * re-serializing a whole page config on every render just to detect a change.
 */
export function hashString(value: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(36);
}
