import { createContext, useContext, useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { brandKitCssVars } from './brand-kit-css-vars.js';
import { brandChartBrand, brandChartPalette } from './brand-kit-chart.js';
import { brandKitLocale } from './brand-kit-format.js';
import { isRendererMode } from '../runtime/host.js';
import { brandKitFontAssets } from './brand-kit-fonts.js';
import {
  brandKitBaseUrl,
  brandKitCollection,
  brandKitLogo,
  brandKitMapStyle,
  isPinnedBrandKitUrl,
  loadBrandKit,
  resolveBrandKitUrl,
} from './brand-kit-assets.js';
import { paginationReadiness } from '../pagination-static/pagination-readiness';
import { ASSET_WAIT_MS } from '../pagination-static/flow-assets.js';
import { useIsoLayoutEffect } from '../utility/use-iso-layout-effect';
import { warnOnce } from '../utility/warn-once.js';
import { brandKitDocumentProblem } from './brand-kit-preview.js';
import { BrandPreviewBar, useBrandPreview, useBrandPreviewBarOwner } from './brand-kit-preview-runtime';

type BrandKitDocument = Record<string, unknown>;
type BrandKitStatus = 'idle' | 'loading' | 'ready' | 'error';

interface BrandKitRuntime {
  brandKit: BrandKitDocument | null;
  cssVars: Record<string, string>;
  sourceUrl: string | undefined;
  status: BrandKitStatus;
  logo: (options?: { kind?: string; background?: 'light' | 'dark'; name?: string; locale?: string }) => ReturnType<typeof brandKitLogo>;
  chartPalette: (options?: { fallback?: string[]; count?: number }) => ReturnType<typeof brandChartPalette>;
  chartBrand: (defaults?: Parameters<typeof brandChartBrand>[1]) => ReturnType<typeof brandChartBrand>;
  /** The brand's default locale and currency (`extensions.locale`); `payload.locale` wins over it. */
  locale: { locale?: string; currency?: string };
  collection: (kind: string, options?: { versionId?: string }) => ReturnType<typeof brandKitCollection>;
  mapStyle: (mode: 'micro' | 'macro') => ReturnType<typeof brandKitMapStyle>;
  resolveUrl: (path: unknown) => string | undefined;
}

interface BrandKitProviderProps {
  /**
   * The kit to render: the payload's kit or the template's bundled default. With `src`, it is
   * what renders until the fetched kit arrives, and what stays when the fetch fails.
   */
  brandKit?: BrandKitDocument | null;
  /** A brandkit.json URL to fetch (see `brandKitSelection`). Relative asset URLs resolve against it. */
  src?: string | null;
  /** Brand values a template opts into beyond colours and fonts: `{ radius: true }` adds `--radius*`. Pass a stable object. */
  adopt?: { radius?: boolean };
  /** Custom properties for whatever the kit leaves out; the kit wins. Pass a stable object. */
  defaults?: Record<string, string>;
  /** Where a `brandKit` passed in came from, so its relative URLs resolve when it has no `baseUrl`. */
  sourceUrl?: string;
  /** Called with each fetched kit. */
  onLoad?: (brandKit: BrandKitDocument) => void;
  /** Called when a fetch fails (the `brandKit` prop keeps rendering). Default: `console.error`. */
  onError?: (error: unknown) => void;
  /** For the scope element. `style` is applied last, so `{ display: 'block' }` gives it a box. */
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}

interface Loaded {
  src: string;
  brandKit: BrandKitDocument | null;
  /** Why it did not load, for the preview bar. */
  error?: string;
}

const BrandKitContext = createContext<BrandKitRuntime | null>(null);

/** A template-relative `src` (`/kits/brandkit.json`) made absolute, so the kit's asset paths resolve. */
function absoluteUrl(url: string) {
  try {
    return typeof location === 'undefined' ? url : new URL(url, location.href).toString();
  } catch {
    return url;
  }
}

/**
 * Scopes a brand kit around its children: the kit's CSS variables on a `display: contents`
 * element, so every `kit-*` and shadcn utility inside resolves and the layout gets no extra box,
 * plus the font stylesheets and `@font-face` rules the kit declares.
 *
 *   import brandKit from './brand/brandkit.json'; // the template's own brand
 *   <BrandKitProvider src={brandKitSelection(payload).src} brandKit={brandKit}>
 *     <PageEditor … />
 *   </BrandKitProvider>
 *
 * On a development host (never in the PDF renderer), `?brand=v9`, a version link or a same-origin
 * path renders that candidate in place of both, under a bar; see brand-kit-preview-runtime.tsx.
 * The mapping and the colour policy are in docs/brand-kit-runtime.md.
 */
export function BrandKitProvider({
  brandKit,
  src,
  adopt,
  defaults,
  sourceUrl,
  onLoad,
  onError,
  className,
  style,
  children,
}: BrandKitProviderProps) {
  const ownUrl = typeof src === 'string' && src.trim() !== '' ? src.trim() : undefined;
  // Development only (`?brand=`): a candidate version renders instead of the template's brand and
  // of `src`. The page URL is its only record; the template's callbacks never see it.
  const preview = useBrandPreview(brandKit);
  const previewUrl = preview && 'url' in preview ? preview.url : undefined;
  const url = previewUrl ?? ownUrl;
  const previewing = previewUrl !== undefined;
  const [loaded, setLoaded] = useState<Loaded | null>(null);
  const notifications = useRef({ onLoad, onError });
  useIsoLayoutEffect(() => { notifications.current = { onLoad, onError }; }, [onLoad, onError]);

  useEffect(() => {
    if (!url) return undefined;
    const controller = new AbortController();
    const fail = (error: unknown) => {
      setLoaded({ src: url, brandKit: null, error: error instanceof Error ? error.message : String(error) });
      if (previewing) console.warn(`[uhuu-components] Brand preview ${url} did not load, so the template's brand renders.`, error);
      else if (notifications.current.onError) notifications.current.onError(error);
      else console.error('[uhuu-components] BrandKitProvider: the kit did not load, so the fallback kit renders.', error);
    };
    const timer = setTimeout(() => {
      controller.abort();
      const error = new Error(`[uhuu-components] BrandKitProvider ${url} is still loading after ${ASSET_WAIT_MS / 1000} s; using the fallback kit.`);
      // The capped readiness hold warns once with this URL; onError reports the fetch failure.
      fail(error);
    }, ASSET_WAIT_MS);
    loadBrandKit(url, { signal: controller.signal }).then(
      (document: BrandKitDocument) => {
        if (controller.signal.aborted) return;
        clearTimeout(timer);
        // A candidate `brand activate` would refuse is not previewed either.
        const problem = previewing ? brandKitDocumentProblem(document) : undefined;
        if (problem) {
          fail(new Error(`${url} is not a current Brand Kit document: ${problem}`));
          return;
        }
        setLoaded({ src: url, brandKit: document });
        if (!previewing) notifications.current.onLoad?.(document);
      },
      (error: unknown) => {
        if (controller.signal.aborted) return;
        clearTimeout(timer);
        fail(error);
      },
    );
    return () => { clearTimeout(timer); controller.abort(); };
  }, [url, previewing]);

  // A print that fetches a brand can change when the brand is republished; the template's own
  // brandkit.json or a pinned `versions/vN` URL cannot.
  useEffect(() => {
    if (url && isRendererMode() && !isPinnedBrandKitUrl(url)) {
      warnOnce(
        `brand-kit-print-fetch:${url}`,
        `[uhuu-components] BrandKitProvider fetches ${url} while printing. Render the template's own brandkit.json, or pin the URL to versions/vN.`,
      );
    }
  }, [url]);

  const current = url && loaded?.src === url ? loaded : null;
  const kit = current?.brandKit ?? brandKit ?? null;
  const kitSource = current?.brandKit && url ? absoluteUrl(url) : sourceUrl;
  const status: BrandKitStatus = !url ? 'idle' : !current ? 'loading' : current.brandKit ? 'ready' : 'error';
  const ownsBar = useBrandPreviewBarOwner(preview);

  const runtime = useMemo<BrandKitRuntime>(() => {
    const base = brandKitBaseUrl(kit, kitSource);
    return {
      brandKit: kit,
      cssVars: brandKitCssVars(kit, { defaults, adopt }),
      sourceUrl: kitSource,
      status,
      logo: (options = {}) => brandKitLogo(kit, { ...options, sourceUrl: kitSource }),
      chartPalette: (options = {}) => brandChartPalette(kit, options),
      chartBrand: (defaults = {}) => brandChartBrand(kit, defaults),
      locale: brandKitLocale(kit),
      collection: (kind, options = {}) => brandKitCollection(kit, kind, { ...options, sourceUrl: kitSource }),
      mapStyle: (mode) => brandKitMapStyle(kit, mode),
      resolveUrl: (path) => resolveBrandKitUrl(path, base),
    };
  }, [kit, kitSource, defaults, adopt, status]);
  const fonts = useMemo(() => brandKitFontAssets(kit, { sourceUrl: kitSource }), [kit, kitSource]);

  // Pagination waits for the kit: its CSS variables and fonts change every flow's layout. While a
  // fetched kit or one of its font stylesheets is loading, `data-uhuu-pagination` stays
  // `measuring`; when they arrive, every flow is measured again.
  const [loadedStylesheets, setLoadedStylesheets] = useState<ReadonlySet<string>>(() => new Set());
  const stylesheetDone = (href: string) => setLoadedStylesheets((done) => (
    done.has(href) ? done : new Set(done).add(href)
  ));
  const pendingStylesheets: string[] = fonts.stylesheetUrls.filter((href: string) => !loadedStylesheets.has(href));
  const pendingKey = pendingStylesheets.join('\n');
  const loadingKit = status === 'loading';
  useIsoLayoutEffect(() => (loadingKit ? paginationReadiness.hold({
    label: `BrandKitProvider ${url}`, waitMs: ASSET_WAIT_MS,
  }) : undefined), [loadingKit, url]);
  useIsoLayoutEffect(() => (pendingKey ? paginationReadiness.hold({
    label: `BrandKitProvider font stylesheet ${pendingKey}`, waitMs: ASSET_WAIT_MS,
  }) : undefined), [pendingKey]);
  useEffect(() => {
    if (!pendingKey) return undefined;
    const timer = setTimeout(() => {
      for (const href of pendingKey.split('\n')) stylesheetDone(href);
    }, ASSET_WAIT_MS);
    return () => clearTimeout(timer);
  }, [pendingKey]);

  return (
    <BrandKitContext.Provider value={runtime}>
      {fonts.stylesheetUrls.map((href) => (
        <link
          key={href}
          rel="stylesheet"
          href={href}
          data-uhuu-brand-kit-font=""
          // A hydrated or cached stylesheet can load before React listens.
          ref={(link) => { if (link?.sheet) stylesheetDone(href); }}
          onLoad={() => stylesheetDone(href)}
          onError={() => {
            // It settles (pagination must not wait), but the text prints in fallback fonts.
            warnOnce(
              `brand-kit-font:${href}`,
              `[uhuu-components] BrandKitProvider font stylesheet ${href} failed to load, so text prints in ` +
              "fallback fonts. Check the kit's font URL."
            );
            stylesheetDone(href);
          }}
        />
      ))}
      {fonts.fontFaceCss ? <style data-uhuu-brand-kit-font="">{fonts.fontFaceCss}</style> : null}
      <div
        data-uhuu-brand-kit={typeof kit?.id === 'string' ? kit.id : ''}
        data-uhuu-brand-kit-status={status}
        className={className}
        style={{ display: 'contents', ...runtime.cssVars, ...style }}
      >
        {children}
      </div>
      {ownsBar && preview ? (
        <BrandPreviewBar
          preview={preview}
          templateKit={brandKit ?? null}
          candidate={previewing ? current?.brandKit ?? null : null}
          status={status === 'ready' ? 'ready' : status === 'error' ? 'error' : 'loading'}
          error={current?.error}
        />
      ) : null}
    </BrandKitContext.Provider>
  );
}

/** The nearest `BrandKitProvider`'s runtime, or `null` outside one. */
export function useBrandKit() {
  return useContext(BrandKitContext);
}
