import * as React from 'react';
import { useDiagnosticWarnings, warnOnce } from '../utility/diagnostics';
import { serializeKeepWithNext } from './flow-measure';
import { FlowTextSplitContext } from './flow-text';
import type { StaticFlowItemMeta, StaticFlowItemGroup, StaticFlowFragmentContext, StaticFlowGroupHeaderFragment, StaticFlowUnplaceableItem, StaticFlowTextSplit } from './flow-types';
/**
 * An item taller than its region gets a page of its own and renders scaled to fit it, so every
 * document keeps all of its content whatever prints it: nothing is clipped, nothing waits on a
 * renderer to reject the page. Its group header stays full size; the item keeps its own layout.
 */
export function unplaceableFitStyle(unplaceable: StaticFlowUnplaceableItem): React.CSSProperties | undefined {
  const room = unplaceable.availableHeight - unplaceable.headerHeight;
  if (!(unplaceable.height > 0) || !Number.isFinite(room)) return undefined;
  const scale = Math.min(1, Math.max(room, 1) / unplaceable.height);
  return scale < 1 ? { transform: `scale(${scale})`, transformOrigin: 'top left' } : undefined;
}

function getItemType(item: unknown): string | undefined {
  if (!item || typeof item !== 'object' || !('type' in item)) return undefined;
  const type = (item as { type?: unknown }).type;
  return typeof type === 'string' || typeof type === 'number' ? String(type) : undefined;
}

function mergeItemMeta(
  base: StaticFlowItemMeta | undefined,
  override: StaticFlowItemMeta | undefined
): StaticFlowItemMeta {
  const merged: StaticFlowItemMeta = { ...(base ?? {}) };

  for (const [key, value] of Object.entries(override ?? {})) {
    if (value !== undefined) {
      (merged as Record<string, unknown>)[key] = value;
    }
  }

  return merged;
}

export function normalizeItemGroup(
  value: StaticFlowItemGroup | string | null | undefined
): StaticFlowItemGroup | undefined {
  if (typeof value === 'string') {
    return value ? { key: value, repeatHeader: true } : undefined;
  }

  if (!value?.key) return undefined;
  return {
    key: value.key,
    repeatHeader: value.repeatHeader !== false,
    ...(value.growSheet ? { growSheet: true } : {}),
  };
}

/**
 * `getFlowFragmentState` resolves the fragment position with `indexOf`. The
 * renderer already walks every visible index, so prepare the same first-match
 * lookup once instead. Keeping the first position deliberately preserves the
 * core helper's behavior for a stale chunk that happens to contain an index
 * more than once.
 */
export function getFirstFragmentPositions(fragmentIndexes: readonly number[]): Map<number, number> {
  const positions = new Map<number, number>();
  fragmentIndexes.forEach((itemIndex, position) => {
    if (!positions.has(itemIndex)) positions.set(itemIndex, position);
  });
  return positions;
}

/**
 * A planned header list is authoritative when it exists, including an empty
 * list. Index it once so a page with many groups does not scan it per item.
 */
export function getPlannedGroupHeadersByItemIndex(
  groupHeaders: StaticFlowGroupHeaderFragment[] | undefined
): Map<number, Set<string>> | undefined {
  if (!groupHeaders) return undefined;

  const headersByItemIndex = new Map<number, Set<string>>();
  for (const header of groupHeaders) {
    let groupKeys = headersByItemIndex.get(header.itemIndex);
    if (!groupKeys) {
      groupKeys = new Set<string>();
      headersByItemIndex.set(header.itemIndex, groupKeys);
    }
    groupKeys.add(header.groupKey);
  }
  return headersByItemIndex;
}

type FlowElementProps = {
  className?: string;
  [attribute: `data-${string}`]: string | number | undefined;
};


function describeNode(node: React.ReactNode): string {
  if (node === null || node === undefined || typeof node === 'boolean') return 'nothing';
  if (Array.isArray(node)) return 'several nodes';
  if (React.isValidElement(node)) return 'a fragment';
  return 'text';
}

/**
 * `asChild`: the flow's attributes and class names go on the element the template returned (a
 * `<tr>`, an `<li>`), Radix Slot style, so nothing stands between the template's container and its
 * items. Classes are joined; the template's style sits over `baseStyle` (getColumnItemProps) and
 * under `forcedStyle` (an oversized item's fit). The element keeps its own ref and key, and gets no
 * `display: flow-root`. Anything but one element cannot carry the attributes: the caller renders
 * its wrapper instead, and development builds say so once per flow and callback.
 */
export function cloneAsChild(
  content: React.ReactNode,
  props: FlowElementProps,
  options: {
    flowId: string;
    source: string;
    baseStyle?: React.CSSProperties;
    forcedStyle?: React.CSSProperties;
  }
): React.ReactElement | null {
  if (React.isValidElement(content) && content.type !== React.Fragment) {
    const own = content.props as { className?: unknown; style?: React.CSSProperties };
    const className = [props.className, typeof own.className === 'string' ? own.className : undefined]
      .filter(Boolean)
      .join(' ') || undefined;
    const style = options.baseStyle || own.style || options.forcedStyle
      ? { ...options.baseStyle, ...own.style, ...options.forcedStyle }
      : undefined;
    return React.cloneElement(content as React.ReactElement<Record<string, unknown>>, {
      ...props,
      className,
      style,
    });
  }
  warnOnce(
    `as-child:${options.flowId}:${options.source}`,
    `[uhuu-components] Flow.Items "${options.flowId}" asChild: ${options.source} returned ` +
    `${describeNode(content)}. asChild needs exactly one element to carry the flow's attributes, ` +
    'so it renders in a wrapper <div> instead.'
  );
  return null;
}

/**
 * An item's or group header's element: the element the template returned carrying the flow's
 * attributes (`asChild`), else a `display: flow-root` wrapper around it. Flow and FlowColumns both
 * render through it, so the same input gives the same markup.
 */
function renderFlowElement(
  content: React.ReactNode,
  className: string | undefined,
  attributes: FlowElementProps,
  options: {
    flowId: string;
    source: string;
    asChild: boolean;
    baseStyle?: React.CSSProperties;
    forcedStyle?: React.CSSProperties;
  }
): React.ReactElement {
  const cloned = options.asChild && cloneAsChild(content, { className, ...attributes }, options);
  if (cloned) return cloned;
  return (
    <div
      className={className}
      style={{ display: 'flow-root', ...options.baseStyle, ...options.forcedStyle }}
      {...attributes}
    >
      {content}
    </div>
  );
}

/** The attributes that carry an item's break rules and group to the measurement pass. */
export function breakAttributes(meta: StaticFlowItemMeta, group: StaticFlowItemGroup | undefined): FlowElementProps {
  return {
    'data-uhuu-flow-break-before': meta.breakBefore ? 'true' : undefined,
    'data-uhuu-flow-break-after': meta.breakAfter ? 'true' : undefined,
    'data-uhuu-flow-keep-with-next': serializeKeepWithNext(meta.keepWithNext),
    'data-uhuu-flow-avoid-break-inside': meta.avoidBreakInside ? 'true' : undefined,
    'data-uhuu-flow-group-key': meta.groupKey,
    'data-uhuu-flow-header-group-key': group?.key,
    'data-uhuu-flow-header-repeat': group ? (group.repeatHeader === false ? 'false' : 'true') : undefined,
  };
}

/** An item's meta: its type's defaults under its own. */
export function resolveItemMeta<TItem, TType extends string>(
  item: TItem,
  index: number,
  resolveItemType: ((item: TItem, index: number) => TType | undefined) | undefined,
  metaDefaults: Partial<Record<TType, StaticFlowItemMeta>> | undefined,
  getItemMeta: ((item: TItem, index: number) => StaticFlowItemMeta | undefined) | undefined
): StaticFlowItemMeta {
  const type = resolveItemType?.(item, index) ?? (getItemType(item) as TType | undefined);
  return mergeItemMeta(type ? metaDefaults?.[type] : undefined, getItemMeta?.(item, index));
}

export function resolveItemClassName<TItem>(
  itemClassName: string | ((item: TItem, index: number) => string | undefined) | undefined,
  item: TItem,
  index: number
): string | undefined {
  return typeof itemClassName === 'function' ? itemClassName(item, index) : itemClassName;
}

/** Development check: `metaDefaults` apply by item type, so some item must have one. */
export function useMetaDefaultsCheck<TItem, TType extends string>(
  component: 'Flow' | 'FlowColumns',
  id: string,
  items: TItem[],
  metaDefaults: Partial<Record<TType, StaticFlowItemMeta>> | undefined,
  resolveItemType: ((item: TItem, index: number) => TType | undefined) | undefined
) {
  const diagnostics = useDiagnosticWarnings();
  React.useEffect(() => {
    if (!diagnostics || !metaDefaults || !Object.keys(metaDefaults).length || !items.length) {
      return;
    }

    const hasResolvableType = items.some((item, index) => (
      Boolean(resolveItemType?.(item, index) ?? getItemType(item))
    ));
    if (hasResolvableType) return;

    warnOnce(
      `meta-defaults:${component}:${id}:${Object.keys(metaDefaults).join('|')}`,
      `[uhuu-components] Static.${component} "${id}" received metaDefaults, but no item type could be resolved. ` +
      'Add a type field to each item or pass getItemType so defaults can be applied.'
    );
  }, [component, id, items, metaDefaults, resolveItemType, diagnostics]);
}

export type FlowItemRendering<TItem> = {
  flowId: string;
  asChild: boolean;
  renderItem: (item: TItem, index: number, fragment: StaticFlowFragmentContext<TItem>) => React.ReactNode;
  renderGroupHeader?: (group: StaticFlowItemGroup, fragment: StaticFlowFragmentContext<TItem>) => React.ReactNode;
  groupHeaderClassName?: string | ((group: StaticFlowItemGroup, fragment: StaticFlowFragmentContext<TItem>) => string | undefined);
};

/**
 * One item of a fragment: its group header, when the fragment opens the group at this item (the
 * plan's header list when there is one, else the fragment's own group rules), and its element.
 * `attributes` are the item's, complete and in the order the caller writes them: Flow and
 * FlowColumns add their own, and the shared break attributes must read the same in both.
 */
export function renderFlowItem<TItem>(
  rendering: FlowItemRendering<TItem>,
  input: {
    item: TItem;
    itemIndex: number;
    fragment: StaticFlowFragmentContext<TItem>;
    group: StaticFlowItemGroup | undefined;
    plannedGroupHeaders: Map<number, Set<string>> | undefined;
    className: string | undefined;
    attributes: FlowElementProps;
    baseStyle?: React.CSSProperties;
    forcedStyle?: React.CSSProperties;
  }
): { header: React.ReactElement | null; element: React.ReactElement } {
  const { flowId, asChild, renderItem, renderGroupHeader, groupHeaderClassName } = rendering;
  const { item, itemIndex, fragment, group, plannedGroupHeaders } = input;
  const hasPlannedGroupHeader = Boolean(group && plannedGroupHeaders?.get(itemIndex)?.has(group.key));
  const shouldRenderGroupHeader = Boolean(
    group &&
    renderGroupHeader &&
    (
      hasPlannedGroupHeader || (
        !plannedGroupHeaders &&
        fragment.isFirstInGroupOnPage &&
        (fragment.isFirstInGroup || group.repeatHeader !== false)
      )
    )
  );
  const header = shouldRenderGroupHeader && group && renderGroupHeader
    ? renderFlowElement(
      renderGroupHeader(group, fragment),
      typeof groupHeaderClassName === 'function' ? groupHeaderClassName(group, fragment) : groupHeaderClassName,
      { 'data-uhuu-flow-group-header': 'true', 'data-uhuu-flow-header-group-key': group.key },
      { flowId, source: 'renderGroupHeader', asChild }
    )
    : null;
  const element = renderFlowElement(renderItem(item, itemIndex, fragment), input.className, input.attributes, {
    flowId,
    source: 'renderItem',
    asChild,
    baseStyle: input.baseStyle,
    forcedStyle: input.forcedStyle,
  });
  return { header, element };
}

/** `data-uhuu-flow-split` on a piece of a split item. */
export function splitPosition(split: StaticFlowTextSplit): 'first' | 'middle' | 'last' {
  if (split.part === 0) return 'first';
  return split.part === split.parts - 1 ? 'last' : 'middle';
}

/**
 * What renderItem's fragment says about a piece: which one it is. A continuation piece resumes its
 * group on the page it opens.
 */
export function splitFragment(split: StaticFlowTextSplit, core: { isFirstInGroupOnPage: boolean }) {
  return {
    split: { part: split.part, parts: split.parts, from: split.from, to: split.to },
    ...(split.part > 0 && core.isFirstInGroupOnPage ? { isGroupContinuation: true } : {}),
  };
}

/** Content inside a piece of an outer Flow's item that is not that piece (a nested Flow's items). */
export function shadowSplit(node: React.ReactNode) {
  return node === null || node === undefined || node === false
    ? node
    : <FlowTextSplitContext.Provider value={null}>{node}</FlowTextSplitContext.Provider>;
}
