/** JSON-shaped template data. Templates own their fields; the shell owns the named maps only. */
import { isPlainObject } from '../../utility/json.js';

export type PayloadRecord = Record<string, unknown>;
export type TemplatePayload = PayloadRecord & {
  pages?: Record<string, PayloadRecord | undefined>;
  groups?: Record<string, PayloadRecord | undefined>;
  integrations?: Record<string, unknown>;
};
export type PayloadUpdate = TemplatePayload | ((previous: TemplatePayload) => TemplatePayload);
export type OutgoingPayload = { sequence: number; payload: TemplatePayload; remainingEchoes?: number };
export type PayloadState = {
  payload: TemplatePayload;
  sequence: number;
  outgoing: OutgoingPayload[];
  lastWrite?: OutgoingPayload;
};

// emitPayload has no acknowledgement or causal id. Bound memory for a host that neither echoes nor
// sends updates of its own (every outstanding snapshot settles when it does).
export const MAX_PENDING_PAYLOADS = 32;
export const isPayloadRecord = (value: unknown): value is PayloadRecord => isPlainObject(value);

/** Reference-fast comparison of JSON data, independent of object key order; no serialization. */
export function equalPayloadValues(left: unknown, right: unknown, seen = new WeakMap<object, object>()): boolean {
  if (Object.is(left, right)) return true;
  if (!isPayloadRecord(left) && !Array.isArray(left)) return false;
  if (!isPayloadRecord(right) && !Array.isArray(right)) return false;
  if (Array.isArray(left) !== Array.isArray(right)) return false;
  if (seen.get(left) === right) return true;
  seen.set(left, right);
  if (Array.isArray(left) && Array.isArray(right) && left.length !== right.length) return false;
  const leftKeys = wireKeys(left as PayloadRecord);
  const rightKeys = wireKeys(right as PayloadRecord);
  return leftKeys.length === rightKeys.length && leftKeys.every((key) =>
    Object.prototype.hasOwnProperty.call(right, key) && equalPayloadValues((left as PayloadRecord)[key], (right as PayloadRecord)[key], seen));
}

function wireKeys(value: PayloadRecord): string[] {
  return Object.keys(value).filter((key) => value[key] !== undefined && typeof value[key] !== 'function' && typeof value[key] !== 'symbol');
}

function sameExternalValues(left: TemplatePayload, right: TemplatePayload, reservedKey: string): boolean {
  const leftKeys = wireKeys(left).filter((key) => key !== reservedKey);
  const rightKeys = wireKeys(right).filter((key) => key !== reservedKey);
  return leftKeys.length === rightKeys.length && leftKeys.every((key) =>
    Object.prototype.hasOwnProperty.call(right, key) && equalPayloadValues(left[key], right[key]));
}

export function createPayloadState(payload?: TemplatePayload): PayloadState {
  return { payload: payload ?? {}, sequence: 0, outgoing: [] };
}

/** A local sequence tracks outstanding snapshots only. It is never written into document data. */
export function updatePayloadState(state: PayloadState, update: PayloadUpdate): PayloadState {
  const payload = typeof update === 'function' ? update(state.payload) : update;
  if (payload === state.payload) return state;
  const write = { sequence: state.sequence + 1, payload };
  return { ...state, payload, sequence: write.sequence, lastWrite: write };
}

/** Only committed snapshots actually sent to the host can be recognized as echoes. */
export function markPayloadSent(state: PayloadState, write: OutgoingPayload, publisherCount = 1): PayloadState {
  if (state.outgoing.some((entry) => entry.sequence === write.sequence)) return state;
  return { ...state, outgoing: [...state.outgoing, { ...write, remainingEchoes: publisherCount }].slice(-MAX_PENDING_PAYLOADS) };
}

/**
 * A payload that matches an outstanding snapshot (reserved key aside) is the host echoing that
 * write: consume one echo per publisher and keep the current payload. Anything else is the host's
 * own update: apply it over the template-owned fields, keep this editor's reserved key, and settle
 * every outstanding snapshot. The channel is ordered, so once the host sends an update of its own
 * no echo of an earlier write can still follow it; and the released editor never echoes, so without
 * settling every write would stay outstanding and a later host update equal to one of them (the
 * user undoing it) would be read as its echo. Known limit: a host update identical to an
 * outstanding write with no other host update in between is read as its echo; emitPayload carries
 * no causal id that could tell them apart.
 */
export function receivePayloadState(state: PayloadState, incoming: TemplatePayload | undefined, reservedKey: string): PayloadState {
  if (!incoming) return state;
  const echo = state.outgoing.findIndex((entry) => sameExternalValues(entry.payload, incoming, reservedKey));
  if (echo !== -1) {
    const remaining = (state.outgoing[echo].remainingEchoes ?? 1) - 1;
    return { ...state, outgoing: remaining ? state.outgoing.map((entry, index) => index === echo ? { ...entry, remainingEchoes: remaining } : entry) : state.outgoing.filter((_, index) => index !== echo) };
  }
  const payload = state.payload[reservedKey] === undefined ? incoming : { ...incoming, [reservedKey]: state.payload[reservedKey] };
  const outgoing = state.outgoing.length ? [] : state.outgoing;
  if (equalPayloadValues(payload, state.payload)) return outgoing === state.outgoing ? state : { ...state, outgoing };
  return { ...state, payload, outgoing };
}
