/**
 * The brand's default locale and currency, which `useBrandKit().locale` exposes; `payload.locale`
 * wins over it in a template.
 *
 * Pure and DOM-free.
 */
import { isPlainObject, textOf } from '../utility/json.js';

/** The brand's default locale and currency (`extensions.locale.strings`). */
export function brandKitLocale(brandKit) {
  const strings = isPlainObject(brandKit) && isPlainObject(brandKit.extensions?.locale?.strings) ? brandKit.extensions.locale.strings : {};
  const locale = textOf(strings.default);
  const currency = textOf(strings.currency);
  return { ...(locale ? { locale } : {}), ...(currency ? { currency } : {}) };
}
